ตัวอย่างนี้สาธิตการใช้งาน FreeRTOS ในรูปแบบของ Arduino Library ( Arduino_FreeRTOS ) โดยมีการสร้าง FreeRTOS Tasks หรือ มีการแบ่งงานออกเป็น 2 ส่วน ดังนี้ BlinkTask : ทำให้ LED กระพริบ ด้วยอัตราคงที่ WiFiScan : ตรวจสอบเครือข่าย Wi-Fi รอบ ๆ และแสดงรายการที่ตรวจพบผ่านทาง Serial #include <Arduino_FreeRTOS.h> #include <WiFiS3.h> // LED pin for Uno R4 WiFi (built-in) const int ledPin = LED_BUILTIN; // WiFi scan interval (in milliseconds) const TickType_t wifiScanDelay = (10000 / portTICK_PERIOD_MS); // LED Blinking Task void BlinkTask(void *pvParameters) { pinMode(ledPin, OUTPUT); while (1) { digitalWrite(ledPin, HIGH); vTaskDelay(500 / portTICK_PERIOD_MS); digitalWrite(ledPin, LOW); vTaskDelay(500 / portTICK_PERIOD_MS); } } // WiFi Scan Task void WifiScanTask(void *pvParameters) { Serial.println("Starting WiFi scan task..."); if (WiFi.status() == WL_NO_MODULE) { Serial.println("No WiFi module detected."); vTaskSuspend(NULL); } while (1) { Serial.println("WiFi scanning..."); int networks = WiFi.scanNetworks(); if (networks == 0) { Serial.println("No Wi-Fi networks found."); } else { Serial.print(networks); Serial.println(" network(s) found:"); for (int i = 0; i < networks; i++) { Serial.print(" "); Serial.print(i + 1); Serial.print(": "); Serial.print(WiFi.SSID(i)); Serial.print(" (RSSI: "); Serial.print(WiFi.RSSI(i)); Serial.print(" dBm, "); printEncryptionType(WiFi.encryptionType(i)); Serial.println(")"); } } vTaskDelay(wifiScanDelay); } } void printEncryptionType(uint8_t type) { switch (type) { case ENC_TYPE_WEP: Serial.print("WEP"); break; case ENC_TYPE_TKIP: Serial.print("WPA"); break; case ENC_TYPE_CCMP: Serial.print("WPA2"); break; case ENC_TYPE_NONE: Serial.print("Open"); break; case ENC_TYPE_AUTO: Serial.print("Auto"); break; default: Serial.print("Unknown"); break; } } void setup() { Serial.begin(115200); while (!Serial); delay(100); // Create FreeRTOS tasks xTaskCreate(BlinkTask, "Blink", 128, NULL, 1, NULL); xTaskCreate(WifiScanTask, "WiFiScan", 512, NULL, 1, NULL); Serial.println("


"); Serial.flush(); // Start the FreeRTOS scheduler vTaskStartScheduler(); } void loop() { } ในตัวอย่างนี้ การทำงานของ FreeRTOS Task Scheduler จะเริ่มทำงานหลังจากเรียกฟังก์ชัน vTaskStartScheduler() แต่ถ้าจะตั้งค่าให้เริ่มทำงานโดยอัตโนมัติ โดยไม่ต้องทำคำสั่งดังกล่าวใน Arduino Sketch ก็มีแนวทางดังนี้ รูป: แนวทางการตั้งค่าให้ FreeRTOS Task Scheduler เริ่มทำงานโดยอัตโนมัติ หากต้องการตรวจสอบ FreeRTOS Config ก็สามารถดูได้จากไฟล์ FreeRTOSConfig.h รูป: ตัวอย่างจากไฟล์ FreeRTOSConfig.h ของไลบรารี ( Arduino_FreeRTOS ) ผู้ใช้สามารถตั้งค่าใช้งานได้ โดยจะต้องแก้ไขไฟล์ FreeRTOSConfig.h Windows : ให้ไปยังไดเรกทอรี C:\Users\%USERNAME%\AppData\Local\Arduino15\packages\arduino\hardware\ แล้วเปิดแก้ไขไฟล์ในไดเรกทอรีต่อไปนี้ ( 1.4.1 คือ ตัวเลขเวอร์ชันของไลบรารีที่ได้ลองใช้งาน) renesas_uno\1.4.1\libraries\Arduino_FreeRTOS\src\FreeRTOSConfig.h ตรวจสอบการตั้งค่าเพิ่มเติม #define configUSE_MUTEXES 1 #define configUSE_RECURSIVE_MUTEXES 1 #define configUSE_TIME_SLICING 1 #define INCLUDE_xTaskGetHandle 1 #define INCLUDE_eTaskGetState 1 ตัวอย่างโค้ดตรวจสอบการตั้งค่าสำหรับ FreeRTOS Configuration #include <Arduino_FreeRTOS.h> // based on FreeRTOS-Kernel-v10.5.1 // Hardware support: Arduino UNO R4 and Arduino Portenta C33 TaskHandle_t task1_handle, task2_handle; void setup() { Serial.begin(115200); while (!Serial); pinMode( LED_BUILTIN, OUTPUT ); digitalWrite( LED_BUILTIN, LOW ); Serial.println( String("configTICK_RATE_HZ : ") + configTICK_RATE_HZ ); Serial.println( String("configCPU_CLOCK_HZ : ") + configCPU_CLOCK_HZ ); Serial.println( String("configMAX_PRIORITIES : ") + configMAX_PRIORITIES ); Serial.println( String("configMINIMAL_STACK_SIZE : ") + configMINIMAL_STACK_SIZE ); Serial.println( String("configUSE_TIME_SLICING : ") + configUSE_TIME_SLICING ); Serial.println( String("configUSE_COUNTING_SEMAPHORES : ") + configUSE_COUNTING_SEMAPHORES ); Serial.println( String("configUSE_MUTEXES : ") + configUSE_MUTEXES ); Serial.println( String("configUSE_RECURSIVE_MUTEXES : " ) + configUSE_RECURSIVE_MUTEXES ); BaseType_t ret_val = xTaskCreate ( task1_func, "Task 1", 128, NULL, 1, &task1_handle ); if (ret_val != pdPASS) { Serial.println( "Failed to create Task 1!!!" ); error_handler(); } ret_val = xTaskCreate ( task2_func, "Task 2", 128, NULL, 1, &task2_handle ); if (ret_val != pdPASS) { Serial.println("Failed to create Task 2!!!"); error_handler(); } Serial.println( "Starting the FreeRTOS scheduler ..."); vTaskStartScheduler(); for(;;); } void loop() { // } void task1_func(void *pvParameters) { (void)pvParameters; // not used TickType_t lastWakeTime = xTaskGetTickCount(); for(;;) { digitalWrite(LED_BUILTIN, LOW ); vTaskDelayUntil( &lastWakeTime, pdMS_TO_TICKS(1000) ); } } void task2_func(void *pvParameters) { (void)pvParameters; // not used vTaskDelay( pdMS_TO_TICKS(500) ); TickType_t lastWakeTime = xTaskGetTickCount(); for(;;) { digitalWrite(LED_BUILTIN, HIGH ); vTaskDelayUntil( &lastWakeTime, pdMS_TO_TICKS(1000) ); } } void error_handler() { Serial.println("The system will be reset...


"); delay(5000); NVIC_SystemReset(); } ตัวอย่างการลองใช้ FreeRTOS Mutex #include <Arduino_FreeRTOS.h> // Global variables int flag = 0; TaskHandle_t task_handle1; TaskHandle_t task_handle2; SemaphoreHandle_t xMutex; void setup() { Serial.begin(115200); while (!Serial); // Create a mutex xMutex = xSemaphoreCreateMutex(); if (xMutex == NULL) { Serial.println( "Mutex creation failed!!!" ); while (1); } int task_stack_size = configMINIMAL_STACK_SIZE; int task_priority = 2; // Create two tasks xTaskCreate(task_func1, "Task 1", task_stack_size, NULL, task_priority, &task_handle1 ); xTaskCreate(task_func2, "Task 2", task_stack_size, NULL, task_priority, &task_handle2 ); // Start the FreeRTOS scheduler. vTaskStartScheduler(); for(;;); } void loop() { // ... } void task_func1(void *pvParameters) { (void)pvParameters; // not used while (1) { // Request the mutex before entering the critical section if (xSemaphoreTake(xMutex, portMAX_DELAY) == pdTRUE) { // Critical section if (flag==0) { flag = 1; Serial.println( String("Task 1: ") + (flag ? "Tick":"Tock") ); Serial.flush(); vTaskDelay(500 / portTICK_PERIOD_MS); } // Release the mutex after leaving the critical section xSemaphoreGive(xMutex); } taskYIELD(); } } void task_func2(void *pvParameters) { (void)pvParameters; // not used while (1) { // Request the mutex before entering the critical section if (xSemaphoreTake(xMutex, portMAX_DELAY) == pdTRUE) { // Critical section if (flag==1) { flag = 0; Serial.println( String("Task 2: ") + (flag ? "Tick":"Tock") ); Serial.flush(); vTaskDelay(500 / portTICK_PERIOD_MS); } // Release the mutex after leaving the critical section xSemaphoreGive(xMutex); } taskYIELD(); } }

ตัวอย่างการเขียนโค้ด MicroPython สำหรับบอร์ด Espressif ESP32 (ตอนที่ 2) # Keywords: Python 3 , MicroPython , Espressif SoCs , ESP32 / ESP32-S3 , Thonny IDE , Arduino Lab for MicroPython , Wokwi Example 10: LED Toggle with SPI Interface Example 11: LED Toggle with RMT Example 12: LED Toggle with PWM Example 13: I/O Follower with GPIO Interrupt Example 14: Pulse Counting with GPIO Interrupt Example 15: Pulse Counting with ESP32 Pulse Counter Example 16: Frequency Measurement with GPIO Interrupt Example 17: Frequency Measurement with ESP32 PCNT Example 18: Button Click Detection with Debounce Logic Example 19: Button Click Detection with Input Sampling Example 20: Notification from ISR to AsyncIO Function ▷ Example 10: LED Toggle with SPI Interface # โค้ดตัวอย่างนี้สาธิตการใช้บัส SPI (Serial Peripheral Interface) เพื่อส่งข้อมูลทีละบิตออกไปด้วยอัตราคงที่ และให้เกิดการสลับสถานะลอจิกของ LED โดยปกติ การเชื่อมต่อแบบ SPI จะต้องมีไมโครคอนโทรลเลอร์ทำหน้าที่เป็นอุปกรณ์ SPI Master และมีอุปกรณ์อย่างน้อยหนึ่งตัวทำหน้าที่เป็น SPI Slave ทั้งสองจะสื่อสารกันโดยใช้สัญญาณต่อไปนี้ ( 4-Wire SPI Bus ) CS คือสัญญาณ Chip Select SCK คือสัญญาณ Serial Clock MOSI คือสัญญาณ Master Out Slave In MISO คือสัญญาณ Master In Slave Out แต่ในตัวอย่างนี้ จะใช้เพื่อส่งข้อมูลบิตตามรูปแบบที่กำหนด (เช่น จำนวน 2 ไบต์) โดยไม่ได้ใช้สำหรับการสื่อสารกับอุปกรณ์อื่น และ ไม่มีอุปกรณ์ SPI Slave ข้อมูลบิตจะถูกเลื่อนหรือส่งออกผ่านทางขา MOSI การกำหนดความถี่ของสัญญาณ SCK สำหรับบัส SPI มีข้อสังเกตดังนี้ ระบบบัสภายในของ ESP32 สำหรับ I/O Peripherals ทำงานที่ความถี่ 80 MHz ดังนั้น ถ้าใช้วงจร SPI Block โดยเฉพาะ เช่น HSPI/SPI1 หรือ VSPI/SPI2 จะใช้ความถี่ของ SPI Bus ได้สูงสุด 80 MHz แต่ถ้าไม่ได้ใช้ขาสำหรับ SPI โดยตรง (ใช้ผ่าน GPIO Multiplexing หมายถึง เลือกใช้ขา GPIO ทั่วไป ไม่ได้เจาะจงสำหรับ Hardware SPI Pins ) ความถี่สูงสุดจะลดลงครึ่งหนึ่ง เหลือไม่เกิน 40 MHz ขาของ SPI Block สำหรับ ESP32 ได้แก่ HSPI (id=1) : SCK=14 , MOSI=13 , MISO=12 , CS=15 VSPI (id=2) : SCK=18 , MOSI=23 , MISO=19 , CS=5 ขาของ ESP32-S3 สำหรับ SPI (มี 4 ชุด คือ SPI0 ~ SPI3 ) SPI0 & SPI1 ( GPIO 26~32 ) จะใช้สำหรับชิป SPI Flash/PSRAM SPI2 (HSPI,id=1) : SCK=12 , MOSI=11 , MISO=13 , CS=10 SPI3 (VSPI,id=2) : SCK=36 , MOSI=35 , MISO=37 , CS=39 การใช้งาน SPI บน MicroPython-ESP32 แบ่งได้เป็น 2 แบบ คือ Hardware SPI ที่ใช้วงจร SPI Block ของ ESP32 โดยตรง และ SoftSPI ( Software/Bit-banged SPI ) ที่ควบคุมด้วยซอฟต์แวร์ รูปแบบแรกรองรับความถี่สูงและมีความแม่นยำกว่า ส่วนรูปแบบที่สองรองรับความถี่ต่ำกว่า และอาจเกิด Clock Jitter (ความไม่สม่ำเสมอของสัญญาณนาฬิกา) ได้ โดยเฉพาะเมื่อมีงานอื่นรันพร้อมกัน แต่ในตัวอย่างนี้ หากใช้กับ LED จำเป็นต้องตั้งค่าความถี่ของ SCK ให้ต่ำพอที่จะมองเห็นการกระพริบได้ และสามารถเลือกใช้ SoftSPI ได้ ในตัวอย่างนี้ ข้อมูลที่จะถูกส่งออกมี 2 ไบต์ หรือ 16 บิต ได้แก่ 0xFF และ 0x00 หมายถึง บิตลอจิก 1 จำนวน 8 บิต และบิตลอจิก 0 อีกจำนวน 8 บิต ตามสัญญาณบิตของ SPI หรือกล่าวได้ว่า ไบต์แรกใช้สัญญาณพัลส์ช่วงที่เป็น High และไบต์ที่สองใช้สัญญาณพัลส์ช่วงที่เป็น Low ถ้าให้ความถี่เท่ากับ 80Hz จะได้สัญญาณเอาต์พุตที่มีความถี่ประมาณ 80Hz / 16 = 5Hz ซึ่งเป็นอัตราการกระพริบของ LED โค้ดตัวอย่าง (สำหรับทดลองใช้กับบอร์ด ESP32-S3 ) มีการเลือกใช้ SPI ( machine.SPI ) และ SoftSPI ( machine.SoftSPI ) ได้สองกรณี เพื่อเปรียบเทียบกัน SPI : ทดลองใช้ความถี่ 8 MHz SoftSPI : ทดลองใช้ความถี่ 80 Hz #------------------------------------------------------------------------- # This script demonstrates how to use SPI / SoftSPI on MicroPython to send # data continuously using hardware SPI or bit-banged SPI on specified pins. #------------------------------------------------------------------------- from machine import Pin, SPI, SoftSPI # Import Pin, SPI and SoftSPI classes USE_HW_SPI = True # True: use machine.SPI, False: use machine.SoftSPI # Use GPIO Multiplexing for SPI or VSPI for ESP32-S3 MOSI = Pin(11) # Assign GPIO11 as MOSI pin (used to drive an LED circuit) SCK = Pin(12) # Assign GPIO12 as SCK pin MISO = Pin(13) # Assign GPIO13 as MISO pin (not used) if USE_HW_SPI: # Use Hardware SPI id=1 SCK_FREQ = 8_000_000 spi = SPI(1, baudrate=SCK_FREQ, polarity=0, phase=0, bits=8, firstbit=SPI.MSB, sck=SCK, mosi=MOSI, miso=MISO ) else: # Use bit-banged SPI (SoftSPI) SCK_FREQ = 80 spi = SoftSPI(baudrate=SCK_FREQ, polarity=0, phase=0, bits=8, firstbit=SPI.MSB, sck=SCK, mosi=MOSI, miso=MISO) data = bytes([0xFF, 0x00]) try: while True: # Continuously write two bytes [0x00, 0xFF] over SPI # Since baudrate is 80Hz, and each transfer sends 16 bits, # this roughly results in a blink rate of 80/16 = 5Hz spi.write(data) except KeyboardInterrupt: print("Terminated...") pass finally: spi.deinit() # Deinitialize (disable) the SPI interface cleanly ตัวอย่างการวัดสัญญาณด้วย USB Logic Analyzer มีดังนี้ รูป: ตัวอย่างรูปคลื่นสัญญาณ MOSI และ SCK สำหรับกรณี SoftSPI (80 Hz) รูป: ตัวอย่างรูปคลื่นสัญญาณ MOSI และ SCK สำหรับกรณี SPI (8 MHz) ▷ Example 11: LED Blink with RMT # โค้ดนี้สาธิตการใช้งานวงจร RMT (Remote Control) Peripheral ภายในชิป ESP32 / ESP32-S3 และใช้คำสั่งจากคลาส esp32.RMT ของ MicroPython เพื่อสร้างสัญญาณพัลส์ซ้ำ ๆ สำหรับกระพริบ LED ที่ต่อกับขา GPIO-11 ด้วยความถี่ประมาณ 10Hz โดยไม่ต้องใช้คำสั่งหน่วงเวลา ( time.sleep ) เพื่อสลับสถานะ LED เอง #------------------------------------------------------------------------- # This script uses the ESP32 RMT peripheral to generate # a repetitive pulse signal to toggle an LED connected to GPIO-11 # at a frequency of about 10Hz. #------------------------------------------------------------------------- from machine import Pin # Import Pin class for GPIO control import time # Import time module for delay functions import esp32 # Import esp32-specific modules (RMT) ledPin = Pin(11, Pin.OUT) # Initialize GPIO-11 as an LED output pin # Create an RMT object on channel 0, outputting pulses on ledPin # The RMT clock runs at 80 MHz. # Dividing by 250 slows this down to 320 kHz timer. # Each pulse length unit corresponds to 1/(80MHz/250) = 3.125 usec. # High pulse length of 32000 correspond to ~100 ms. CLK_DIV = 250 rmt = esp32.RMT(id=0, pin=ledPin, clock_div=CLK_DIV) rmt.loop(True) # Enable continuous looping of pulses # Write pulses to RMT: # The list [32000, 32000] specifies the pulse widths (in timer ticks) # for low and high signals. # The second parameter '0' means the pulses start with the low signal. rmt.write_pulses([32000, 32000], 0) try: while True: # The main loop (do nothing) time.sleep(1) except KeyboardInterrupt: print("Terminated...") finally: rmt.loop(False) # Disable pulse looping (stop repeating pulses) rmt.deinit() # Deinitialize the RMT peripheral to free resources วงจร RMT จะถูกตั้งค่าให้แบ่งความถี่สัญญาณนาฬิกาภายในจาก 80 MHz ลงมาเป็น 320 kHz เมื่อใช้ตัวหารความถี่เท่ากับ 256 ทำให้หนึ่งหน่วยความยาวพัลส์มีค่า 3.125 µsec จากนั้นกำหนดความยาวพัลส์ 32000 หน่วย สำหรับสถานะ Low และ High อย่างละหนึ่งช่วง (ความกว้างพัลส์ประมาณ 100 msec และคาบเวลาของสัญญาณเอาต์พุตประมาณ 200 msec ) ทำให้ LED กระพริบอัตโนมัติจนกว่า จะหยุดโปรแกรม หรือปิดการทำงานของ RMT การคำนวณหาความกว้างของสัญญาณพัลส์ มีดังนี้ 	ext{Pulse Width (msec)} =  rac{ CLK\_DIV 	imes 32000 }{ 80	imes 10^6 	ext{ Hz}} 	imes 10^3 ตัวอย่างการวัดสัญญาณด้วย USB Logic Analyzer มีดังนี้ รูป: ตัวอย่างรูปคลื่นสัญญาณ GPIO-11 (เมื่อใช้ค่า CLK_DIV = 250 ) วัดความกว้างของพัลส์ได้ 100 msec รูป: ตัวอย่างรูปคลื่นสัญญาณ GPIO-11 (เมื่อใช้ค่า CLK_DIV = 1 ) วัดความกว้างของพัลส์ได้ 400 usec ▷ Example 12: LED Blink with PWM # โค้ดนี้สาธิตการใช้งานวงจร LEDC ของ ESP32 / ESP32-S3 และใช้คำสั่งจากคลาส machine.PWM ของ MicroPython เพื่อสร้างสัญญาณ PWM (Pulse Width Modulation) ซึ่งเป็นสัญญาณดิจิทัลที่มีคาบ ( Periodic Signal ) สามารถนำมาใช้ เพื่อทำให้ LED กระพริบได้ โดยตั้งค่า Duty Cycle เท่ากับ 50% แต่จะต้องใช้ความถี่ไม่สูงมากนัก ในกรณีของ ESP32-S3 ความถี่ PWM ต่ำสุดที่ฮาร์ดแวร์รองรับได้อยู่ที่ประมาณ 10 Hz ดังนั้นหากต้องการความถี่ต่ำกว่านี้ ต้องใช้วิธีสร้างสัญญาณด้วยซอฟต์แวร์แทน #-------------------------------------------------------------- # Example: Generate the lowest-frequency PWM on a selected pin # to blink an LED continuously. #-------------------------------------------------------------- from machine import Pin, PWM import t