eOut pin pulseInPin = Pin(11, Pin.IN, Pin.PULL_UP) pulseInPin.irq(trigger=Pin.IRQ_RISING | Pin.IRQ_FALLING, handler=irq_handler) try: while True: # Main loop time.sleep(1) except KeyboardInterrupt: print("Terminated...") finally: pwm.deinit() ตัวอย่างการวัดสัญญาณด้วย USB Logic Analyzer มีดังนี้ รูป: การวัดสัญญาณที่ขา GPIO-11 & GPIO-12 จากรูปคลื่นสัญญาณจะเห็นได้ว่า สัญญาณอินพุตที่ขา GPIO-11 เป็นสัญญาณพัลส์ที่มีความถี่ 10kHz และสัญญาณเอาต์พุตที่ขา GPIO-12 ตอบสนองต่อเหตุการณ์ขอบขาขึ้นหรือขาลงของสัญญาณอินพุต เมื่อเกิดขอบขาขึ้นหรือขาลงบนสัญญาณอินพุต จะมีระยะเวลาตอบสนองสำหรับสัญญาณเอาต์พุต ( 16 ~ 22 usec โดยประมาณ) ระยะเวลาดังกล่าวประกอบด้วยสองส่วนคือ Interrupt Latency และการเขียนค่าเพื่ออัปเดตเอาต์พุตในฟังก์ชัน ISR และมีผลต่อความถี่สูงสุดของสัญญาณอินพุตที่สามารถตอบสนองได้ทัน ▷ Example 14: Pulse Counting with GPIO Interrupt # โค้ดนี้สาธิตการใช้วงจร RMT ของ ESP32 เพื่อสร้างสัญญาณพัลส์ออกที่ขา GPIO-13 โดยสัญญาณจะมีพัลส์ระดับสูงคงที่ 50 ไมโครวินาที และพัลส์ระดับต่ำที่มีความกว้างสุ่มในช่วง 50 ถึง 200 ไมโครวินาที สัญญาณเอาต์พุตที่ขา GPIO-13 จะถูกเชื่อมต่อกลับเข้ามายังขา GPIO-11 เป็นอินพุต และมีการเปิดใช้งานอินเทอร์รัพท์ เพื่อจับการเปลี่ยนแปลงของสัญญาณที่ขาอินพุตในขอบขาขึ้น ทุกครั้งที่มีขอบขาขึ้น ฟังก์ชันขัดจังหวะจะเพิ่มตัวนับพัลส์ จำนวนพัลส์ที่ตรวจจับได้จะแสดงผลหลังจากส่งสัญญาณพัลส์แต่ละครั้ง #-------------------------------------------------------------- # This script generates a variable pulse pattern using # the ESP32 RMT peripheral on GPIO-13 and counts the number of # rising pulses detected on GPIO-11 using an interrupt handler. # The output pulse pattern consists of fixed 50 µs high pulses # and random low pulse widths between 50 and 200 µs. # GPIO-13 (RMT output) should be connected physically to # GPIO-11 (input) for pulse counting. #-------------------------------------------------------------- from machine import Pin from esp32 import RMT import time import random pulseInPin = Pin(11, Pin.IN, Pin.PULL_UP) pulseOutPin = Pin(13, Pin.OUT) pulse_count = 0 # store the num