Frequency measurement") while True: print(50*"-") for f in test_frequencies: pwm.freq( f ) # Set the PWM frequency await asyncio.sleep_ms(2*timer_period_ms) while not done: await asyncio.sleep_ms(5) freq = 1000.0 * saved_pulse_count / timer_period_ms print(f"Frequency [Hz]: {f:.1f} set, {freq:.1f} measured") await asyncio.sleep(1) # wait before next measurement try: asyncio.run(main()) except KeyboardInterrupt: print("Terminated...") finally: pwm.deinit() timer.deinit() รูป: การสาธิตการทำงานของโค้ดตัวอย่างโดยใช้ Arduino Lab for MicroPython โดยมีการสร้างสัญญาณทดสอบที่มีความถี่แตกต่างกัน ตั้งแต่ 100 Hz จนถึง 20 kHz ตัวอย่างการวัดสัญญาณด้วย USB Logic Analyzer มีดังนี้ รูป: สัญญาณทดสอบความถี่ 100 Hz รูป: สัญญาณทดสอบความถี่ 20 kHz หากจำลองการทำงานด้วย Wokwi Simulator ก็สามารถวัดความถี่ของสัญญาณทดสอบเสมือนจริงได้ ในรูปเป็นการทดสอบกับบอร์ด ESP32 และมีการเลือกใช้ขา GPIO-12 เป็นอินพุต และเชื่อมต่อกับขา เอาต์พุต GPIO-13 แต่มีข้อสังเกตว่า ค่าความถี่วัดได้ถูกต้องสำหรับความถี่ต่ำ แต่หากใช้ความถี่สูง เช่น 5000 Hz หรือมากกว่า จะวัดค่าได้ไม่ถูกต้อง รูป: การจำลองการทำงานด้วย Wokwi Simulator โดยใช้บอร์ด ESP32 DevKit-C ▷ Example 17: Frequency Measurement with ESP32 PCNT # โค้ดนี้เป็นตัวอย่างการวัดความถี่ของสัญญาณ PWM ด้วยการใช้วงจร PCNT (Pulse Counter) ของ ESP32 นับจำนวนพัลส์ที่เกิดขึ้นในช่วงเวลาที่กำหนด โดยมีการทำงานหลักดังนี้: สร้างสัญญาณ PWM ออกที่ขา GPIO13 เพื่อใช้เป็นสัญญาณทดสอบ ใช้วงจร PCNT สำหรับสัญญาณอินพุตที่ขา GPIO-11 นับจำนวนขอบขาขึ้นของสัญญาณ PWM ตั้งค่าตัวจับเวลาฮาร์ดแวร์ให้ทำงานแบบเป็นรอบ ( Periodic ) เช่น ทุก 20 มิลลิวินาที เพื่อเรียกใช้ฟังก์ชันวัดความถี่ สร้างฟังก์ชันเพื่ออ่านค่าจำนวนพัลส์ที่นับได้ ในช่วงเวลาก่อนหน้า แล้วรีเซ็ตตัวนับพัลส์สำหรับรอบถัดไป ใช้ตัวแปร done เพื่อสลับสถานะการอ่านและรีเซ็ตตัวนับพัลส์ ในลูปหลักจะตั้งค่าความถี่ PWM ให้เปลี่ยนไปตามรายการทดสอบ และแสดงผลความถี่ที่วัดได้เปรียบเทียบกับค่าที่ตั้งไว้ #-------------------------------------------------------------- # This script measures the frequency of a PWM signal by using # the PCNT block inside the ESP32 to count the number of # rising edges detected within a fixed time window. # Note that he ESP32 PCNT hardware uses a 16-bit signed counter # internally. This means the counter max is +32767. #-------------------------------------------------------------- import uasyncio as asyncio from machine import Pin, PWM, Timer from esp32 import PCNT import time # Global variables done = False saved_pulse_count = 0 # Setup PWM output pwmOutPin = Pin(13, Pin.OUT) pwm = PWM(pwmOutPin) pwm.duty_u16(32768) # 50% duty cycle pwm.freq(1000) # 1 kHz test PWM (default) # Setup PCNT (Pulse Counter) on GPIO11 to count pulses from PWM pulseInPin = Pin(11, Pin.IN, pull=Pin.PULL_UP) # Create pulse counter on PCNT unit 0 pcnt = PCNT(0, pulseInPin) pcnt.init(pin=pulseInPin,rising=PCNT.INCREMENT, falling=PCNT.IGNORE, filter=10) pcnt.start() # Start pulse counting def measure_freq(timer): global pcnt, saved_pulse_count, done if not done: # Read current pulse count from PCNT saved_pulse_count = pcnt.value() else: # Clear PCNT value pcnt.value(0) done = not done # Setup a periodic timer to measure frequency timer_period_ms = 20 # msec timer = Timer(0) timer.init(period=timer_period_ms, mode=Timer.PERIODIC, callback=measure_freq) def format_freq(freq): if freq >= 1_000_000: return "{:6.2f} MHz".format(freq / 1_000_000) elif freq >= 1_000: return "{:6.2f} kHz".format(freq / 1_000) else: return "{:6.2f} Hz".format(freq) # Main async. function async def main(): global saved_pulse_count, timer_period_ms, done test_frequencies = [100, 500, 1_000, 5_000, 10_000, 50_000, 1_000_000] print( "
Frequency measurement") while True: print(50*"-") for f in test_frequencies: pwm.freq( f ) # Set the PWM frequency await asyncio.sleep_ms(2*timer_period_ms) while not done: await asyncio.sleep_ms(5) freq = 1000.0 * saved_pulse_count / timer_period_ms f_measured = format_freq(freq) f_set = format_freq(f) print(f"Frequency: {f_set} set, {f_measured} measured") await asyncio.sleep(1) # wait before next measurement try: asyncio.run(main()) except KeyboardInterrupt: print("Terminated...") finally: pwm.deinit() pcnt.deinit() timer.deinit() รูป: การสาธิตการทำงานของโค้ดตัวอย่างโดยใช้ Arduino Lab for MicroPython โดยมีการสร้างสัญญาณทดสอบที่มีความถี่แตกต่างกัน ตั้งแต่ 100 Hz จนถึง 1 MHz ▷ Example 18: Button Click Detection with Debounce Logic # โค้ดนี้แสดงตัวอย่างการใช้ Hardware Timer ของ ESP32 ในการอ่านค่าจากปุ่มกด ( Push Button ) เช่น ทุก ๆ 10 มิลลิวินาที ( 10 msec ) เมื่อเกิดอินเทอร์รัปต์จากวงจร Timer ฟังก์ชัน Timer Callback จะทำการตรวจสอบการเปลี่ยนแปลงสถานะของปุ่มกด พร้อมกับจับเวลาสำหรับสถานะลอจิก Low ที่คงที่ อย่างน้อย 50 msec เพื่อกรองสัญญาณเด้ง ( Bouncing ) ที่เกิดขึ้นทั้งช่วงกดและปล่อยปุ่ม ซึ่งช่วยให้การตรวจจับการกดปุ่มมีความแม่นยำและถูกต้องมากขึ้น from machine import Pin, Timer import time SAMPLE_PERIOD_MS = 10 # Sampling interval (10 msec) DEBOUNCE_MS = 50 # Minimum stable time to confirm press buttonPin = Pin(2, Pin.IN, Pin.PULL_UP) # Push button (active low) last_btn_value = buttonPin.value() last_stable_value = last_btn_value last_change_time = time.ticks_ms() click_detected = False def timer_callback(timer): global last_btn_value, last_stable_value global last_change_time, click_detected value = buttonPin.value() # Read current button state now = time.ticks_ms() # Read current time (in msec) if value != last_btn_value: # Button state change detected last_btn_value = value # Save the last button state last_change_time = now # Reset debounce timer else: # Stable button state if time.ticks_diff(now, last_change_time) >= DEBOUNCE_MS: if value != last_stable_value: last_stable_value = value if value == 0: # active-low press detected click_detected = True timer = Timer(0) timer.init(period=SAMPLE_PERIOD_MS, mode=Timer.PERIODIC, callback=timer_callback) try: while True: # Main loop if click_detected: click_detected = False # Reset for next press print("Click detected..") time.sleep(0.01) except KeyboardInterrupt: print("Terminated...") finally: timer.deinit() ตัวอย่างการวัดสัญญาณด้วย USB Logic Analyzer มีดังนี้ รูป: การวัดสัญญาณจากวงจรปุ่มกดภายนอกเมื่อมีการกดปุ่มหนึ่งครั้ง (วัดความกว้างช่วง Low ได้ประมาณ 59.3 msec ) รูป: การวัดสัญญาณจากวงจรปุ่มกดภายนอกเมื่อมีการกดปุ่มหนึ่งครั้ง (วัดความกว้างช่วง Low ได้ประมาณ 31.9 msec ) รูป: ช่วงเวลาที่มีการกระเด้งของปุ่มกดเมื่อมีการปล่อยปุ่มแล้ว รูป: ตัวอย่างการทดสอบโค้ดโดยใช้ Wokwi Simulator แบบเสมือนจริง รูป: ตัวอย่างการทดสอบโค้ดโดยใช้บอร์ด ESP32-S3 ▷ Example 19: Button Click Detection with Input Sampling # โค้ดนี้ใช้เทคนิคเพื่ออ่านค่าอินพุตด้วยอัตราคงที่ ( Input Sampling ) เช่น ทุก ๆ 10 มิลลิวินาที แล้วเก็บค่าบิตไว้ในตัวแปร โดยเลื่อนบิตเข้าทาง LSB ( Left-Shift Register ) แต่จำกัดไว้ไม่เกิน 8 บิต จากนั้นใช้ค่าของตัวแปรนี้ตรวจหาลำดับบิตที่บ่งบอกว่าปุ่มกดหรือปล่อยจริง ทำให้สามารถกรองสัญญาณเด้ง ( Bounce ) และตรวจจับการคลิกได้โดยไม่ต้องหน่วงเวลาในหลักโปรแกรม ปุ่มกดภายนอกทำงานแบบ Active-Low ดังนั้น ถ้ายังไม่มีการกดปุ่ม ค่าของตัวแปรจะเป็น 0b11111111 หรือ 0xFF และถ้ามีการกดปุ่ม ค่าบิตบางตำแหน่งจะเริ่มเปลี่ยนเป็น 0 แต่ถ้าปล่อยปุ่มจะเปลี่ยนกลับเป็น 1 การตรวจสอบขอบสัญญาณอินพุตจะเป็นไปตามเงื่อนไข: 0xF0 หมายถึง ขอบขาลง ซึ่งหมายความว่า สัญญาณจะต้องเปลี่ยนเป็น 0 ต่อเนื่องกัน 4 บิต (เท่ากับ 4 x 10 = 40 msec ) 0x0F หมายถึง ขอบขาขึ้น ซึ่งหมายความว่า สัญญาณจะต้องเปลี่ยนเป็น 1 ต่อเนื่องกัน 4 บิต (เท่ากับ 4 x 10 = 40 msec ) #-------------------------------------------------------------- # This example implements button click detection by periodically # sampling the button input using a hardware timer of the ESP32. # A 8-bit shift register is used to debounce the button signal # by tracking recent samples to detect stable press and # release patterns. # The timer ISR updates the sample state and sets a flag when # a click is detected, allowing the main loop to respond # asynchronously without blocking or excessive polling. #-------------------------------------------------------------- from machine import Pin, Timer import time SAMPLE_PERIOD_MS = 10 # Sampling interval buttonPin = Pin(2, Pin.IN, Pin.PULL_UP) # Push button (active low) saved_value = 0xFF state = 0 click_detected = False def timer_callback(timer): global state, saved_value, click_detected saved_value = ((saved_value << 1) | int(buttonPin.value())) & 0xFF if saved_value == 0xF0 and state == 0: # Button pressed state = 1 click_detected = False elif saved_value == 0x0F and state == 1: # Button released state = 0 click_detected = True elif saved_value == 0xFF: state = 0 timer = Timer(0) timer.init(period=SAMPLE_PERIOD_MS, mode=Timer.PERIODIC, callback=timer_callback) try: clicks = 0 # Total click count while True: # Main loop if click_detected: clicks += 1 click_detected = False # Reset for next press print(f"Click detected.. total clicks: {clicks}") time.sleep(0.01) except KeyboardInterrupt: print("Terminated...") finally: timer.deinit() รูป: ตัวอย่างการทดสอบโค้ดโดยใช้ Wokwi Simulator แบบเสมือนจริง ▷ Example 20: Notification from ISR to AsyncIO Function # ตัวอย่างนี้ใช้วงจร Hardware Timer ของ ESP32 เพื่อสลับสถานะขาออก pinA ภายในฟังก์ชัน ISR ( Timer Callback )ทุก ๆ 1 มิลลิวินาที พร้อมกับตั้งค่า ThreadSafeFlag เพื่อแจ้งเตือนไปยังลูปหลักซึ่งรอรับสัญญาณและสลับสถานะขาออก pinB #-------------------------------------------------------------- # This example uses a hardware timer on the ESP32 to toggle # one output pin (pinA) inside the timer ISR every 1 ms. # The ISR also sets a ThreadSafeFlag to notify the asynchronous # main loop, which toggles a second output pin (pinB) # each time it receives the notification. #-------------------------------------------------------------- import uasyncio as asyncio from uasyncio import ThreadSafeFlag from machine import Pin, Timer pinA = Pin(12, Pin.OUT) pinB = Pin(11, Pin.OUT) pinA.off() pinB.off() # Create the flag for notification from ISR to async. function flag = ThreadSafeFlag() # Timer callback (ISR) def timer_callback(timer): pinA.toggle() # Toggle pin A flag.set() # Notify main loop timer = Timer(0) timer.init(period=1, mode=Timer.PERIODIC, callback=timer_callback) async def main(): while True: await flag.wait() # Wait until timer ISR sets the flag pinB.toggle() # Toggle pin B try: asyncio.run(main()) except KeyboardInterrupt: print("Terminated...") finally: timer.deinit() ตัวอย่างการวัดสัญญาณด้วย USB Logic Analyzer มีดังนี้ รูป: การวัดสัญญาณ pinA กับ pinB และวัดระยะเวลาในการตอบสนอง เมื่อฟังก์ชัน main() ได้รับการแจ้งเตือนจากฟังก์ชัน ISR ในแต่ละครั้ง (วัดระยะเวลาตอบสนองได้ประมาณ 90 usec ) ▷ กล่าวสรุป # บทความนี้ได้นำเสนอเนื้อหาตอนที่ 2 ที่มีตัวอย่างการเขียนโค้ด เพื่อใช้งาน GPIO (ดิจิทัล) ของ ESP32 เบื้องต้น เช่น การใช้งาน LED เป็นเอาต์พุต และการใช้ปุ่มกดแบบ Push Button เป็นอินพุต ได้มีการนำเสนอและเปรียบเทียบรูปแบบการเขียนโค้ดที่แตกต่างกันสำหรับการใช้คำสั่ง หรือไลบรารีต่าง ๆ ของ MicroPython และมีตัวอย่างการวัดสัญญาณด้วย USB Logic Analyzer เพื่อศึกษาพฤติกรรมการทำงานของโค้ด MicroPython และช่วยให้เข้าใจหลักการทำงานของ MicroPython สำหรับ ESP32 / ESP32-S3 ได้ดีขึ้น บทความถัดไป: " ตัวอย่างการเขียนโค้ด MicroPython สำหรับบอร์ด Espressif ESP32 (ตอนที่ 3) This work is licensed under a Creative Commons Attribution-ShareAlike 4.0 International License . Created: 2025-08-12 | Last Updated: 2025-08-14

การใช้คำสั่ง pulseIn() ของ Arduino API เป็นการทำคำสั่งซ้ำ เพื่อคอยตรวจสอบดูสถานะลอจิกที่ขาสัญญาณ Echo และดูว่า มีการเปลี่ยนแปลงขอบขาขึ้น ( Rising Edge ) และขอบขาลง ( Falling Edge ) หรือไม่ และเมื่อเกิดเหตุการณ์ทั้งสองกรณี ก็จะมีการบันทึกเวลา หรือ Timestamps แล้วนำมาลบกัน เพื่อให้ได้ความกว้างของพัลส์ ( Pulse Width ) โค้ดตัวอย่างนี้สาธิตการเปิดใช้งานอินเทอร์รัพท์ของไมโครคอนโทรลเลอร์ โดยใช้คำสั่งของ Arduino API เช่น attachInterrupt() และมีการสร้างฟังก์ชัน echo_isr() เพื่อทำหน้าที่เป็น Interrupt Service Routine (ISR) ซึ่งจะถูกเรียกให้ทำงานเมื่อเกิดเหตุการณ์ขอบขาขึ้นหรือขาลงที่ขา Echo เมื่อฟังก์ชัน echo_isr() ทำงาน ก็จะอ่านค่าเวลาของระบบ หน่วยเป็นไมโครวินาที แล้วบันทึกลงในอาร์เรย์ชื่อ timestamps ในตำแหน่ง 0 ถ้าเกิดเหตุการณ์ขอบขาขึ้น และในตำแหน่ง 1 ถ้าเกิดขอบขาลง เมื่อต้องการวัดระยะทาง ก็ให้สร้างสัญญาณพัลส์ที่ขา Trigger แล้วเปิดใช้งานอินเทอร์รัพท์ และรอเวลาประมาณ 50 มิลลิวินาที หากมีเหตุการณ์ขอบขาขึ้นและขาลงเกิดขึ้นตามลำดับที่ขา Echo ก็ให้อ่านค่าเวลาที่ได้บันทึกไว้ในอาร์เรย์ที่ตำแหน่ง timestamps[1] และ timestamps[0] แล้วนำค่ามาลบกัน จึงจะได้ความกว้างของพัลส์ที่เกิดขึ้น #define SOUND_SPEED (342) #define US_TO_CM(t) ((SOUND_SPEED*t)/20000.0) #define ECHO_PIN (16) #define TRIG_PIN (17) void setup() { pinMode( ECHO_PIN, INPUT ); pinMode( TRIG_PIN, OUTPUT ); Serial.begin( 115200 ); Serial.println( "


HC-SR04 Ultrasonic Sensor Demo" ); Serial.flush(); digitalWrite( TRIG_PIN, LOW ); delay(20); while ( digitalRead( ECHO_PIN) ) { delay(1); } } volatile uint32_t timestamps[2] = {0,0}; IRAM_ATTR void echo_isr() { // ISR code executed from SRAM uint32_t t_now = micros(); // Get the current time (usec) if ( digitalRead( ECHO_PIN ) ) { // rising-edge event timestamps[0] = t_now; // Save the timestamp. } else { // falling-edge event timestamps[1] = t_now; // Save the timestamp. } } uint32_t read_sensor() { // Clear timestamps for rising-edge and falling-edge events. timestamps[0] = timestamps[1] = 0; // Enable GPIO interrrupt on the Echo pin. attachInterrupt( ECHO_PIN, echo_isr, CHANGE ); // Create a short pulse on the Trigger pin. digitalWrite( TRIG_PIN, HIGH ); delayMicroseconds( 10 ); digitalWrite( TRIG_PIN, LOW ); // Wait for 50 msec. delay(50); // Disable the interrupt on the Echo pin. detachInterrupt( ECHO_PIN ); // Check the timestamps for valid pulse width if ( timestamps[0] < timestamps[1] ) { return (timestamps[1] - timestamps[0]); } return 0; // no pulse } void loop() { uint32_t t_usec = read_sensor(); Serial.print( "distance(cm): " ); if ( t_usec == 0 ) { // no pulse detected Serial.println( "---" ); } else { Serial.printf( "%.1f
", US_TO_CM(t_usec) ); } delay(100); }

ชิป ESP32 มีวงจรภายในที่เรียกว่า RMT (Remote Control Transceiver) เหมาะสำหรับการส่งหรือรับชุดข้อมูลบิตด้วยแสงอินฟราเรด ตัวอย่างนี้สาธิตการใช้ฟังก์ชันที่ได้มีการประกาศไว้ในไฟล์ esp32-hal-rmt.h เช่น rmtInit() , rmtSetTick() , rmtRead() เป็นต้น เพื่อเปิดใช้งาน RMT Channel และอินเทอร์รัพท์ที่เกี่ยวข้องสำหรับการรับข้อมูลจากโมดูลอินฟราเรด วงจร RMT จะทำหน้าที่ตรวจสอบดูว่า มีสัญญาณพัลส์เข้ามาหรือไม่ และให้วัดความกว้างของพัลส์ช่วงที่เป็น Low และ High ตามลำดับ แล้วบันทึกลงในโครงสร้างข้อมูล ( rmt_data_t ) #if !defined(ESP32) #error "This Arduino sketch is targeted at ESP32." #endif #include "esp32-hal-rmt.h" // https://github.com/espressif/arduino-esp32/blob/master/cores/esp32/esp32-hal-rmt.h // Set the GPIO pin for IR receiver #define IR_PIN (GPIO_NUM_18) #define BUF_SIZE (128) #define HEADER_MARK_MIN (8000) #define TIMEOUT_MS (70) #define HEADER_MARK_MAX (HEADER_MARK_MIN+2000) #define HEADER_SPACE_MIN (4000) #define HEADER_SPACE_MAX (HEADER_SPACE_MIN+1000) #define REPEAT_SPACE_MIN (2000) #define REPEAT_SPACE_MAX (REPEAT_SPACE_MIN+1000) #define BIT_MARK_MIN (500) #define BIT_MARK_MAX (BIT_MARK_MIN+200) #define INVALID_CODE (0x00000000) #define REPEATED_CODE (0xffffffff) rmt_obj_t* rmt_recv = NULL; uint32_t rmt_tick; #define BUF_SIZE (128) volatile uint32_t pulse_widths_count; volatile uint16_t pulse_widths[ BUF_SIZE ]; IRAM_ATTR void rmt_recv_data_callback( uint32_t *rmt_data, size_t len, void *arg ) { rmt_data_t* data = (rmt_data_t*)rmt_data; pulse_widths_count = 2*len; if ( 0 < len && pulse_widths_count < BUF_SIZE ) { for ( int i=0; i < len; i++ ) { pulse_widths[2*i] = data[i].duration0; // low pulse width pulse_widths[2*i+1] = data[i].duration1; // high pulse width } } else { pulse_widths_count = 0; } } void setup() { Serial.begin( 115200 ); delay( 1000 ); Serial.println( "

ESP32 - RMT IR Receiver Demo..." ); Serial.flush(); // Initialize the RMT channel to capture up to 192 items. rmt_recv = rmtInit( IR_PIN, RMT_RX_MODE, RMT_MEM_192 ); if ( rmt_recv != NULL ) { Serial.println( "Initialized RMT Receiver..." ); } // Set RMT tick period (in usec): 1 usec. rmt_tick = rmtSetTick(rmt_recv, 1000) / 1000; Serial.printf( "RMT tick = %lu usec
", rmt_tick ); // Set RMT receive filter. rmtSetFilter( rmt_recv, true, 255 ); // Set RMT receiver threshold. rmtSetRxThreshold( rmt_recv, 10000 / rmt_tick ); // Set RMT receiver callback. rmtRead( rmt_recv, rmt_recv_data_callback, NULL ); } void loop() { uint32_t ir_code = ir_decode(); if ( ir_code != INVALID_CODE ) { if ( ir_code == REPEATED_CODE ) { Serial.println( "Repeated Code" ); } else { Serial.print( "Code: " ); Serial.println( ir_code, HEX ); } } delay(5); } uint32_t ir_decode() { uint32_t ret_code = INVALID_CODE; int32_t n = pulse_widths_count-2; // 'n' must be an even number. volatile uint16_t *p = pulse_widths; if ( n <= 0 ) return ret_code; if ( HEADER_MARK_MIN < p[0] && p[0] < HEADER_MARK_MAX ) { if ( HEADER_SPACE_MIN < p[1] && p[1] < HEADER_SPACE_MAX ) { // message header found uint32_t code = 0; for ( uint32_t i=2; i < n; i+=2 ) { if ( BIT_MARK_MIN < p[i] && p[i] < BIT_MARK_MAX ) { code = (code << 1) | (p[i+1] > BIT_MARK_MAX); } else { // bit timing error code = INVALID_CODE; break; } } // end-for if ( code != INVALID_CODE ) { ret_code = code; } } else if ( REPEAT_SPACE_MIN < p[1] && p[1] < REPEAT_SPACE_MAX ) { // repeated code found ret_code = REPEATED_CODE; } } pulse_widths_count = 0; return ret_code; }
